    if m in stack: return False
    o=ol(m)
    if not os.path.exists(o): memo[m]=("no-olean",); return memo[m]
    if os.path.getmtime(o) < os.path.getmtime(paths[m]): memo[m]=("src-newer",); return memo[m]
    for dep in edges.get(m,[]):
        if dep not in paths: continue
        r=dirty(dep, stack+(m,))
        if r: memo[m]=("dep:"+dep.split('.')[-1]+":"+r[0],); return memo[m]
        od=ol(dep)
        if os.path.exists(od) and os.path.getmtime(od) > os.path.getmtime(o):
            memo[m]=("dep-olean-newer:"+dep.split('.')[-1],); return memo[m]
    memo[m]=None; return None
